class Solution {
public:
    bool splitArraySameAverage(vector<int>& nums) {
        int n = nums.size();
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (n == 1) return false;
        vector<int> t(n);
        for (int i = 0; i < n; i++) t[i] = n * nums[i] - total;
        int mid = n / 2;
        unordered_set<int> left_sums = {0};
        for (int i = 0; i < mid; i++) {
            vector<int> temp(left_sums.begin(), left_sums.end());
            for (int s : temp) left_sums.insert(s + t[i]);
        }
        unordered_set<int> right_sums = {0};
        for (int i = mid; i < n; i++) {
            vector<int> temp(right_sums.begin(), right_sums.end());
            for (int s : temp) right_sums.insert(s + t[i]);
        }
        int total_left = 0, total_right = 0;
        for (int i = 0; i < mid; i++) total_left += t[i];
        for (int i = mid; i < n; i++) total_right += t[i];
        left_sums.erase(0);
        left_sums.erase(total_left);
        if (left_sums.count(0)) return true;
        for (int s : right_sums) {
            if (s != 0 && s != total_right && s == 0) return true;
        }
        for (int s : left_sums) {
            if (right_sums.count(-s)) return true;
        }
        return false;
    }
};

class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        int total = 0;
        for (int x : nums) total += x;
        if (n == 1) return false;
        int[] t = new int[n];
        for (int i = 0; i < n; i++) t[i] = n * nums[i] - total;
        int mid = n / 2;
        Set<Integer> leftSums = new HashSet<>();
        leftSums.add(0);
        for (int i = 0; i < mid; i++) {
            Set<Integer> next = new HashSet<>(leftSums);
            for (int s : leftSums) next.add(s + t[i]);
            leftSums = next;
        }
        Set<Integer> rightSums = new HashSet<>();
        rightSums.add(0);
        for (int i = mid; i < n; i++) {
            Set<Integer> next = new HashSet<>(rightSums);
            for (int s : rightSums) next.add(s + t[i]);
            rightSums = next;
        }
        int totalLeft = 0, totalRight = 0;
        for (int i = 0; i < mid; i++) totalLeft += t[i];
        for (int i = mid; i < n; i++) totalRight += t[i];
        leftSums.remove(0);
        leftSums.remove(totalLeft);
        if (leftSums.contains(0)) return true;
        for (int s : leftSums) {
            if (rightSums.contains(-s)) return true;
        }
        return false;
    }
}

var splitArraySameAverage = function(nums) {
    const n = nums.length;
    const total = nums.reduce((a, b) => a + b, 0);
    if (n === 1) return false;
    const t = nums.map(x => n * x - total);
    const mid = Math.floor(n / 2);
    let leftSums = new Set([0]);
    for (let i = 0; i < mid; i++) {
        const next = new Set(leftSums);
        for (const s of leftSums) next.add(s + t[i]);
        leftSums = next;
    }
    let rightSums = new Set([0]);
    for (let i = mid; i < n; i++) {
        const next = new Set(rightSums);
        for (const s of rightSums) next.add(s + t[i]);
        rightSums = next;
    }
    let totalLeft = 0;
    for (let i = 0; i < mid; i++) totalLeft += t[i];
    leftSums.delete(0);
    leftSums.delete(totalLeft);
    if (leftSums.has(0)) return true;
    for (const s of leftSums) {
        if (rightSums.has(-s)) return true;
    }
